// Источник: web-тесты .qa/e2e/tests/zmanim/zm-01-rows-method-names-mobile.spec.ts и zm-01-rows-method-names-desktop.spec.ts, план .qa/e2e/specs/zmanim.md,
// кейс .qa/tests/zmanim/ZM-01-rows-and-method-names.md. Тикет #6a86f7df.
// На устройстве одна ширина (экран телефона) вместо 320/360/390/1440; id DOM (#zman-…) заменены текстами;
// сравнение CSS шрифта метода и имени — только web (ручная по скриншоту).
import { $$, expect, driver } from '@wdio/globals';
import { byText, byTextContains, scrollToText } from '../../helpers/ui.ts';
import { hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

/** Экран «זמני היום»: deep link (APP_SCHEME), иначе — с главной по ссылке/карточке (название уточнить на устройстве). */
async function openZmanim() {
  if (hasDeepLinks()) await openRoute('/zmanim');
  else {
    await toHome();
    for (const name of ['זמני היום', 'זמני התפילות', 'זמנים']) {
      const el = await scrollToText(name, 6).catch(() => null);
      if (el) { await el.click(); break; }
    }
  }
  await (await byTextContains('שקיעת החמה')).waitForDisplayed({ timeout: 25000 });
}
/** Элементы, текст которых содержит подстроку (все). */
function allContains(part: string) {
  return driver.isAndroid
    ? $$(`android=new UiSelector().textContains("${part}")`)
    : $$(`-ios predicate string:label CONTAINS "${part}"`);
}
/** Элементы со временем «H:MM» (возможны невидимые метки направления ‎ вокруг). */
function allTimes() {
  return driver.isAndroid
    ? $$('android=new UiSelector().textMatches(".*\\d{1,2}:\\d{2}.*")')
    : $$('-ios predicate string:label MATCHES ".*[0-9]{1,2}:[0-9]{2}.*"');
}
/** Есть время на той же строке (по вертикали), что и элемент. */
async function timeOnSameLine(el: El) {
  const a = await el.getLocation();
  const h = (await el.getSize()).height;
  for (const t of await allTimes()) {
    const b = await t.getLocation();
    if (Math.abs(b.y - a.y) < Math.max(12, h / 2)) return true;
  }
  return false;
}

describe('זמני היום', () => {
  afterEach(async () => { await toHome(); });

  it('ZM-01 Строки זמנים: имя + час рядом, полное название метода, без переносов #6a86f7df @prod-safe', async () => {
    // 1. Открыть «זמני היום».
    await openZmanim();

    // 2. «בין השמשות»: время на той же строке; полное название метода (רבנו תם, 13.5 דקות לפני, 7.083°) — ниже имени.
    const bein = await scrollToText('בין השמשות');
    expect(await timeOnSameLine(bein)).toBe(true);
    const beinMethod = await byTextContains('13.5 דקות לפני');
    await expect(beinMethod).toBeDisplayed();
    const beinMethodText = await beinMethod.getText();
    expect(beinMethodText).toContain('רבנו תם');
    expect(beinMethodText).toMatch(/7\.083°/);
    expect(beinMethodText).not.toContain('ר״ת');
    expect((await beinMethod.getLocation()).y).toBeGreaterThan((await bein.getLocation()).y + 10);

    // «צאת הכוכבים» — время рядом и свой метод (רבנו תם, 72 דקות).
    const tzeit = await scrollToText('צאת הכוכבים');
    expect(await timeOnSameLine(tzeit)).toBe(true);
    const tzeitMethods: string[] = [];
    for (const el of await allContains('72 דקות')) tzeitMethods.push(await el.getText());
    expect(tzeitMethods.some((t) => t.includes('רבנו תם'))).toBe(true);

    // «סוף זמן קריאת שמע (מג״א, 72 דקות)» — имя и метод в одну строку (высота как у однострочного «בין השמשות»).
    await scrollToText('(מג״א, 72 דקות)');
    const sofMethod = await byText('(מג״א, 72 דקות)');
    await expect(sofMethod).toBeDisplayed();
    const lineH = (await (await byText('בין השמשות')).getSize().catch(() => ({ height: 0 }))).height;
    const sofNames = await allContains('סוף זמן קריאת שמע');
    expect(sofNames.length).toBeGreaterThan(0);
    for (const n of sofNames) {
      if (lineH > 0) expect((await n.getSize()).height).toBeLessThan(lineH * 1.6);
    }
    if (lineH > 0) expect((await sofMethod.getSize()).height).toBeLessThan(lineH * 1.6);
  });
});
